mapper.select:
SELECT pt.*, u.name AS teacher_name, c.name AS class_name FROM practice_task pt LEFT JOIN sys_user u ON pt.teacher_id = u.id LEFT JOIN sys_class c ON pt.class_id = c.id
pt.deleted = 0
AND ${ew.sqlSegment}

mapper.delete:
DELETE FROM practice_task
WHERE deleted = 1
AND IFNULL(update_time, create_time) < #{threshold}
